"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[18083],{18083:function(n){n.exports=JSON.parse('{"content":"\\n## Antigravity CLI: Gemini CLI is now Antigravity CLI\\n\\nAs of June 18, 2026, the <mark>Gemini CLI</mark> service has been discontinued.  \\nThis applies to all tiers — free, Pro, and Ultra — and users have been migrated to use <mark>Antigravity CLI</mark> as the successor.\\n\\n### Install\\n```sh\\n{\\n    \\"title\\": \\"Install Antigravity CLI\\"\\n}\\n---\\n$ curl -fsSL https://antigravity.google/cli/install.sh | bash\\n```\\n\\n### Usage\\nAfter installation, you can launch the CLI with the <mark>agy</mark> command.\\n```sh\\n{\\n    \\"title\\": \\"Run Antigravity CLI\\"\\n}\\n---\\n$ agy\\n```\\n"}')}}]);